<?php
function mka_agenda_schema($db){$db->query("CREATE TABLE IF NOT EXISTS suite_agenda_settings(id INT NOT NULL PRIMARY KEY,enabled TINYINT NOT NULL DEFAULT 0,start_time CHAR(5) NOT NULL DEFAULT '12:00',end_time CHAR(5) NOT NULL DEFAULT '13:00',workdays VARCHAR(20) NOT NULL DEFAULT '0,1,2,3,4,5,6') ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");if(!$db->query("SHOW COLUMNS FROM suite_agenda_settings LIKE 'workdays'")->fetch_assoc())$db->query("ALTER TABLE suite_agenda_settings ADD workdays VARCHAR(20) NOT NULL DEFAULT '0,1,2,3,4,5,6'");$db->query('INSERT IGNORE INTO suite_agenda_settings(id) VALUES(1)');$db->query('INSERT IGNORE INTO suite_agenda_settings(id,enabled,start_time,end_time,workdays) SELECT 2,enabled,start_time,end_time,workdays FROM suite_agenda_settings WHERE id=1');}
function mka_agenda_settings($db,$kind='ticket'){$id=$kind==='installation'?2:1;$r=$db->query('SELECT enabled,start_time,end_time,workdays FROM suite_agenda_settings WHERE id='.$id)->fetch_assoc();return array('enabled'=>(bool)$r['enabled'],'start'=>$r['start_time'],'end'=>$r['end_time'],'days'=>$r['workdays']===''?array():array_map('intval',explode(',',$r['workdays'])));}
function mka_agenda_settings_save($db,$data,$kind='ticket'){if(!is_bool($data['enabled']??null))throw new InvalidArgumentException('Configuração inválida.');foreach(array('start','end') as $key)if(!is_string($data[$key]??null)||!preg_match('/^(?:[01]\d|2[0-3]):[0-5]\d$/D',$data[$key]))throw new InvalidArgumentException('Informe horários válidos.');if($data['start']>=$data['end'])throw new InvalidArgumentException('O fim do almoço precisa ser depois do início.');$days=$data['days']??mka_agenda_settings($db,$kind)['days'];if(!is_array($days)||count($days)>7)throw new InvalidArgumentException('Dias de trabalho inválidos.');foreach($days as $day)if(!is_int($day)||$day<0||$day>6)throw new InvalidArgumentException('Dia de trabalho inválido.');$days=array_values(array_unique($days));sort($days);$workdays=implode(',',$days);$enabled=(int)$data['enabled'];$id=$kind==='installation'?2:1;$q=$db->prepare('UPDATE suite_agenda_settings SET enabled=?,start_time=?,end_time=?,workdays=? WHERE id=?');$q->bind_param('isssi',$enabled,$data['start'],$data['end'],$workdays,$id);$q->execute();}
function mka_agenda_lunch($settings,$time){return $settings['enabled']&&$time>=$settings['start']&&$time<$settings['end'];}
function mka_agenda_workday($settings,$day){return in_array((int)(new DateTimeImmutable($day))->format('w'),$settings['days'],true);}
